// Reads the Error Trigger payload defensively (M-C): its shape changes between
// versions, and this workflow runs exactly when something has already gone wrong. If it
// blows up reading a property of undefined, the original failure is lost entirely.
const e = $input.first().json ?? {};

const workflow    = e.workflow?.name ?? 'unknown';
const executionId = String(e.execution?.id ?? '');
const node        = e.execution?.error?.node?.name
                 ?? e.execution?.error?.node
                 ?? e.execution?.lastNodeExecuted
                 ?? 'unknown';
const message     = e.execution?.error?.message ?? 'no detail';
const url         = e.execution?.url ?? '';

const when = DateTime.now()
  .setZone('America/Costa_Rica')
  .toFormat('dd/MM/yyyy HH:mm');

const text =
  `FAILURE IN ${workflow}\n\n` +
  `When: ${when}\n` +
  `Node: ${node}\n` +
  `Error: ${message}\n` +
  (executionId ? `Execution: ${executionId}\n` : '') +
  (url ? `\n${url}` : '');

return [{ json: { workflow, executionId, node, message, text } }];

parameters.query:
insert into bot.errors (workflow, execution_id, node, message)
values ($1, $2, $3, $4)
returning id;
